(6134444, 903420, 96751, '<td valign="top">This is a very intriguing image.  For a moment, I almost thought I was up in a spaceship, looking down upon the earth through the clouds.  Or on a ship, looking down into the ocean.  Very cool.</td>', 'This is a very intriguing image.  For a moment, I almost thought I was up in a spaceship, looking down upon the earth through the clouds.  Or on a ship, looking down into the ocean.  Very cool.', '2010-08-18 17:05:25.000000', NULL, 1),
(6134445, 903307, 96751, '<td valign="top">Wonderful reflections.  Both on the water, and of the sunset, as well as the shoreline on the right.  Compositionally, the railing on the left has way too much weight for the delicacy of the rest of the image.</td>', 'Wonderful reflections.  Both on the water, and of the sunset, as well as the shoreline on the right.  Compositionally, the railing on the left has way too much weight for the delicacy of the rest of the image.', '2010-08-18 17:06:14.000000', NULL, 1),
(6134446, 904061, 96751, '<td valign="top">Wonderful!  It looks like jewelry.  I love the gradient sky, and how complementary all the colors are.  The swirling shapes are also terrific.  Front page.</td>', 'Wonderful!  It looks like jewelry.  I love the gradient sky, and how complementary all the colors are.  The swirling shapes are also terrific.  Front page.', '2010-08-18 17:06:56.000000', NULL, 1),
(6134448, 903558, 96751, '<td valign="top">I think mirrored buildings are a gift to architecture.  And these windows look like little cushions.</td>', 'I think mirrored buildings are a gift to architecture.  And these windows look like little cushions.', '2010-08-18 17:07:31.000000', NULL, 1),
(6134449, 903969, 96751, '<td valign="top">If this is Disney Hall, one of these days we''ll have to do a GTG in LA!</td>', 'If this is Disney Hall, one of these days we''ll have to do a GTG in LA!', '2010-08-18 17:08:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6134451, 904195, 96751, '<td valign="top">There is something very appealing about this image.  I love the boldness of that red, but perhaps it''s just a bit cramped with the crop.</td>', 'There is something very appealing about this image.  I love the boldness of that red, but perhaps it''s just a bit cramped with the crop.', '2010-08-18 17:08:36.000000', NULL, 1),
(6134453, 903844, 96751, '<td valign="top">Nice reflection.  Is this off the holy water font?  Or did you bring a mirror with you :-)</td>', 'Nice reflection.  Is this off the holy water font?  Or did you bring a mirror with you :-)', '2010-08-18 17:09:26.000000', NULL, 1),
(6134454, 904118, 96751, '<td valign="top">Very different from most entries, which depict modern architecture.  This is such a cool image.  Needs some home improvement....</td>', 'Very different from most entries, which depict modern architecture.  This is such a cool image.  Needs some home improvement....', '2010-08-18 17:10:11.000000', NULL, 1),
(6134456, 903878, 96751, '<td valign="top">Great pattern image.  Not sure it''s "architecture", but it is terrific.  I have something similar (not in a challenge) with orange seats.  I could look at this for hours.  The quality of this image should place it on the front page, if voters can agree it''s architecture.</td>', 'Great pattern image.  Not sure it''s "architecture", but it is terrific.  I have something similar (not in a challenge) with orange seats.  I could look at this for hours.  The quality of this image should place it on the front page, if voters can agree it''s architecture.', '2010-08-18 17:11:23.000000', NULL, 1),
(6134457, 903560, 96751, '<td valign="top">I really like the simplicity of the lines and the strong colors.  Nicely processed.</td>', 'I really like the simplicity of the lines and the strong colors.  Nicely processed.', '2010-08-18 17:11:56.000000', NULL, 1),
(6134459, 904204, 96751, '<td valign="top">Gotham City!!!!  Great pp''ing.</td>', 'Gotham City!!!!  Great pp''ing.', '2010-08-18 17:12:37.000000', NULL, 1),
(6134461, 904113, 96751, '<td valign="top">Great eye!  This is so beautiful and clean.  Just that touch of sun is so transformational.  Front page.</td>', 'Great eye!  This is so beautiful and clean.  Just that touch of sun is so transformational.  Front page.', '2010-08-18 17:13:03.000000', NULL, 1),
(6134463, 904185, 96751, '<td valign="top">Hey, I have the missing upper piece of the tower!  Together we have the whole bridge :-)</td>', 'Hey, I have the missing upper piece of the tower!  Together we have the whole bridge :-)', '2010-08-18 17:13:36.000000', NULL, 1),
(6134464, 904166, 96751, '<td valign="top">Churches provide such an opportunity for patterns and symmetry.  Great shot</td>', 'Churches provide such an opportunity for patterns and symmetry.  Great shot', '2010-08-18 17:13:55.000000', NULL, 1),
(6134465, 903976, 96751, '<td valign="top">I don''t know what the EMP is, but it sure is colorful!</td>', 'I don''t know what the EMP is, but it sure is colorful!', '2010-08-18 17:14:21.000000', NULL, 1),
(6134466, 904205, 96751, '<td valign="top">I like how this completely fills the frame.</td>', 'I like how this completely fills the frame.', '2010-08-18 17:14:43.000000', NULL, 1),
(6134469, 904069, 96751, '<td valign="top">Brilliant.  Took me a moment to find the demarcation point.  Very well scene and processed.  Front page, and a contender for the top three.</td>', 'Brilliant.  Took me a moment to find the demarcation point.  Very well scene and processed.  Front page, and a contender for the top three.', '2010-08-18 17:15:23.000000', NULL, 1),
(6134470, 903814, 96751, '<td valign="top">Simple and nice.</td>', 'Simple and nice.', '2010-08-18 17:16:02.000000', NULL, 1),
(6134471, 904092, 96751, '<td valign="top">Love the name!  It looks like you might have been using a polarizing lens, which gives a bit of a dull finish to the image.</td>', 'Love the name!  It looks like you might have been using a polarizing lens, which gives a bit of a dull finish to the image.', '2010-08-18 17:16:47.000000', NULL, 1),
(6134472, 903397, 96751, '<td valign="top">The grunge treatment really adds a personality to this place.  Great shadows and textures, and the arches lead the eye to the end.</td>', 'The grunge treatment really adds a personality to this place.  Great shadows and textures, and the arches lead the eye to the end.', '2010-08-18 17:17:45.000000', NULL, 1),
(6134475, 903181, 96751, '<td valign="top">Very homey and appealing.  Great colors, which repeat throughout the image.</td>', 'Very homey and appealing.  Great colors, which repeat throughout the image.', '2010-08-18 17:18:32.000000', NULL, 1),
(6134479, 903993, 96751, '<td valign="top">O.M.G.  This is my pick for the blue.  Awesome choice to turn it upside down (which I figured out as I contorted trying to figure out what it was).  Brilliant.  I love the rippled texture of the "sky", and how it just "hovers" over the rest of the scene.  Well done!</td>', 'O.M.G.  This is my pick for the blue.  Awesome choice to turn it upside down (which I figured out as I contorted trying to figure out what it was).  Brilliant.  I love the rippled texture of the "sky", and how it just "hovers" over the rest of the scene.  Well done!', '2010-08-18 17:20:22.000000', NULL, 1),
(6134480, 904200, 96751, '<td valign="top">Excellent conversion!</td>', 'Excellent conversion!', '2010-08-18 17:20:34.000000', NULL, 1),
(6134481, 903089, 96751, '<td valign="top">Love those columns and the Chihuly!</td>', 'Love those columns and the Chihuly!', '2010-08-18 17:20:54.000000', NULL, 1),
(6134482, 903468, 96751, '<td valign="top">Great POV.  Nicely seen</td>', 'Great POV.  Nicely seen', '2010-08-18 17:21:08.000000', NULL, 1),
(6134483, 903948, 96751, '<td valign="top">Incredible detail and colors.  Looks organic, like a tin man.  Front page.</td>', 'Incredible detail and colors.  Looks organic, like a tin man.  Front page.', '2010-08-18 17:21:35.000000', NULL, 1),
(6134485, 904073, 96751, '<td valign="top">Very nice lines, but there is a murkiness to this image that I cannot figure out.</td>', 'Very nice lines, but there is a murkiness to this image that I cannot figure out.', '2010-08-18 17:22:09.000000', NULL, 1),
(6134486, 903835, 96751, '<td valign="top">Great lines and reflections.</td>', 'Great lines and reflections.', '2010-08-18 17:22:20.000000', NULL, 1),
(6134488, 904147, 96751, '<td valign="top">At first, I though that the overly dark figures would be a detriment to the image, but they just serve to accentuate the strong vertical lines and colors.</td>', 'At first, I though that the overly dark figures would be a detriment to the image, but they just serve to accentuate the strong vertical lines and colors.', '2010-08-18 17:23:03.000000', NULL, 1),
(6134648, 904007, 118396, '<td valign="top">The Helix Bridge is just a phenomenal structure.  Can''t go wrong there!</td>', 'The Helix Bridge is just a phenomenal structure.  Can''t go wrong there!', '2010-08-18 20:25:36.000000', NULL, 1),
(6134653, 903993, 40391, '<td valign="top">Inverting this image really transform it from a nice picture to art.  It doesnt'' fully meet the challenge in my opinion (or at least my expectations) but using my scoring formula I''m glad to give this a 9.  Well done!</td>', 'Inverting this image really transform it from a nice picture to art.  It doesnt'' fully meet the challenge in my opinion (or at least my expectations) but using my scoring formula I''m glad to give this a 9.  Well done!', '2010-08-18 20:28:42.000000', NULL, 1),
(6134708, 904061, 103142, '<td valign="top">This is an awesome find, but something seems a little off in the processing; it seems a little flat. I''m not sure if it just needs more contrast, or a bit more crispness. 7 for the interesting capture, but I think it could be an 8 or 9 with some playing.</td>', 'This is an awesome find, but something seems a little off in the processing; it seems a little flat. I''m not sure if it just needs more contrast, or a bit more crispness. 7 for the interesting capture, but I think it could be an 8 or 9 with some playing.', '2010-08-18 21:41:19.000000', NULL, 1),
(6134709, 903449, 103142, '<td valign="top">Whoa! Majorly cool photo! Good luck with this one.</td>', 'Whoa! Majorly cool photo! Good luck with this one.', '2010-08-18 21:41:45.000000', NULL, 1),
(6134711, 903578, 103142, '<td valign="top">Nice POV. I like the tilt in this one.</td>', 'Nice POV. I like the tilt in this one.', '2010-08-18 21:42:13.000000', NULL, 1),
(6134712, 903337, 103142, '<td valign="top">oh, what a cool idea! I like your POV on this one. Though I''m curious what it would have looked like if you had cropped up a little from the bottom and in a bit from the right. The bottom building looks a little heavy for such a flowing image. Perhaps it''s just because it''s so dark on the left? Maybe just lightening the shadows through shadows/highlights would work instead of cropping...? <br/> <br/>Just thinking out loud... (voting later)</td>', 'oh, what a cool idea! I like your POV on this one. Though I''m curious what it would have looked like if you had cropped up a little from the bottom and in a bit from the right. The bottom building looks a little heavy for such a flowing image. Perhaps it''s just because it''s so dark on the left? Maybe just lightening the shadows through shadows/highlights would work instead of cropping...?  Just thinking out loud... (voting later)', '2010-08-18 21:42:31.000000', NULL, 1),
(6134713, 903307, 103142, '<td valign="top">This is quite eye catching!  Wish the composition could have been a little different. The object on the left is interesting, but a little awkward. Still a very striking photo. (voting later)</td>', 'This is quite eye catching!  Wish the composition could have been a little different. The object on the left is interesting, but a little awkward. Still a very striking photo. (voting later)', '2010-08-18 21:43:28.000000', NULL, 1),
(6134714, 903894, 103142, '<td valign="top">Gave it a 7, and then noticed the truck. Definite 8 with the truck. :)</td>', 'Gave it a 7, and then noticed the truck. Definite 8 with the truck. :)', '2010-08-18 21:44:18.000000', NULL, 1),
(6134719, 904185, 103142, '<td valign="top">It''s a fun shot, but I wish you could have isolated the simpler part of the bridge more. The disappearing bridge is great, but the building and the chunkier part of the bridge on the left are very busy and distract the eye. There''s something almost lyrical about the simplicity of the rest of the image.<br/> <br/>It still rates a 7, because the disappearing bridge part is wonderful. But if you could have found a different angle, isolating that part of the bridge, it could certainly have been a 9 or 10!</td>', 'It''s a fun shot, but I wish you could have isolated the simpler part of the bridge more. The disappearing bridge is great, but the building and the chunkier part of the bridge on the left are very busy and distract the eye. There''s something almost lyrical about the simplicity of the rest of the image. It still rates a 7, because the disappearing bridge part is wonderful. But if you could have found a different angle, isolating that part of the bridge, it could certainly have been a 9 or 10!', '2010-08-18 21:44:43.000000', NULL, 1),
(6134720, 903468, 103142, '<td valign="top">This is such a great angle! But you''re losing some detail in the pillars and circle that could be brought out a couple of different ways: If you use photoshop, the shadows/highlights command could help. Also, Topaz would be excellent on this shot!<br/> <br/>My apologies if you already thought of these and chose to edit it this way. I just thought I''d make suggestions in case you hadn''t considered it. It''s such an interesting shot. (voting later)</td>', 'This is such a great angle! But you''re losing some detail in the pillars and circle that could be brought out a couple of different ways: If you use photoshop, the shadows/highlights command could help. Also, Topaz would be excellent on this shot! My apologies if you already thought of these and chose to edit it this way. I just thought I''d make suggestions in case you hadn''t considered it. It''s such an interesting shot. (voting later)', '2010-08-18 21:45:22.000000', NULL, 1),
(6134721, 903122, 103142, '<td valign="top">Very interesting -- nice find.</td>', 'Very interesting -- nice find.', '2010-08-18 21:45:55.000000', NULL, 1),
(6134722, 903521, 103142, '<td valign="top">Very intriguing! (not voting yet)</td>', 'Very intriguing! (not voting yet)', '2010-08-18 21:46:20.000000', NULL, 1),
(6134723, 904058, 103142, '<td valign="top">Intriguing! (voting later, but I found this quite interesting. I wonder what it would look like with a tad more contrast?)</td>', 'Intriguing! (voting later, but I found this quite interesting. I wonder what it would look like with a tad more contrast?)', '2010-08-18 21:46:41.000000', NULL, 1),
(6134724, 903993, 103142, '<td valign="top">This is really quite cool! I have no idea what I''m looking at, but it''s very interesting. (not voting at the moment)</td>', 'This is really quite cool! I have no idea what I''m looking at, but it''s very interesting. (not voting at the moment)', '2010-08-18 21:46:44.000000', NULL, 1),
(6134726, 903969, 103142, '<td valign="top">That''s pretty cool -- very escheresque!</td>', 'That''s pretty cool -- very escheresque!', '2010-08-18 21:46:54.000000', NULL, 1),
(6134730, 904144, 103142, '<td valign="top">I like this quite a bit. Nice find.</td>', 'I like this quite a bit. Nice find.', '2010-08-18 21:48:25.000000', NULL, 1),
(6134878, 904068, 83313, '<td valign="top">I initially gave this a neutral 5, and felt I had to give it some further consideration. After reading up on the definition of architecture, it does indeed fit a wider definition of the term. Bumping this up a bit now. Based on the high quality of the image itself and the discussions in the forum, I think this could be the entry from <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=58785" rel="nofollow" target="_blank">Focuspoint</a>.</td>', 'I initially gave this a neutral 5, and felt I had to give it some further consideration. After reading up on the definition of architecture, it does indeed fit a wider definition of the term. Bumping this up a bit now. Based on the high quality of the image itself and the discussions in the forum, I think this could be the entry from  Focuspoint.', '2010-08-19 00:43:41.000000', NULL, 1),
(6134968, 904082, 117298, '<td valign="top">I like this, a compelling photo - kind of old-timey looking with the noise. It looks like the horizon might be slightly off-level.</td>', 'I like this, a compelling photo - kind of old-timey looking with the noise. It looks like the horizon might be slightly off-level.', '2010-08-19 03:00:54.000000', NULL, 1),
(6135020, 903548, 100002, '<td valign="top">this is a great bw pic. Love the composition and the sky... Great shot!</td>', 'this is a great bw pic. Love the composition and the sky... Great shot!', '2010-08-19 05:28:23.000000', NULL, 1),
