(6135061, 903890, 77543, '<td valign="top">This would have been better if it was taken from the centre instead of slightly to one side. Otherwise this is an excellent shot.</td>', 'This would have been better if it was taken from the centre instead of slightly to one side. Otherwise this is an excellent shot.', '2010-08-19 08:30:46.000000', NULL, 1),
(6135063, 903746, 59737, '<td valign="top">I think a straight on picture with more of the reflection (if possible) and maybe a black and white conversion would work well for this building.</td>', 'I think a straight on picture with more of the reflection (if possible) and maybe a black and white conversion would work well for this building.', '2010-08-19 08:32:22.000000', NULL, 1),
(6135064, 903948, 59737, '<td valign="top">Really liking all the modern looks in the challenge, not sure what this building is (or if it''s a building) but this is a great detail</td>', 'Really liking all the modern looks in the challenge, not sure what this building is (or if it''s a building) but this is a great detail', '2010-08-19 08:34:33.000000', NULL, 1),
(6135066, 904144, 59737, '<td valign="top">like this, pretty simple, think it would look nice with a black and white conversion as well.</td>', 'like this, pretty simple, think it would look nice with a black and white conversion as well.', '2010-08-19 08:36:29.000000', NULL, 1),
