(6138726, 904007, 64989, '<td valign="top">I love everything about this.  The light, the color, the composition.  Beautiful.</td>', 'I love everything about this.  The light, the color, the composition.  Beautiful.', '2010-08-23 14:01:57.000000', NULL, 1),
(6138730, 904070, 64989, '<td valign="top">This is stunning, a lovely picture of a beautiful building.  <br/>My only preference would have been to level the shot, I feel a little tipped over in it, and that''s distracting to me.</td>', 'This is stunning, a lovely picture of a beautiful building.  My only preference would have been to level the shot, I feel a little tipped over in it, and that''s distracting to me.', '2010-08-23 14:05:10.000000', NULL, 1),
(6138732, 904169, 64989, '<td valign="top">Amazing.  I went "ooohh" as soon as I saw it.  Graphic and elegant.  My No. 1 of the challenge.</td>', 'Amazing.  I went "ooohh" as soon as I saw it.  Graphic and elegant.  My No. 1 of the challenge.', '2010-08-23 14:05:53.000000', NULL, 1),
(6138734, 904091, 64989, '<td valign="top">The capture of the beams of light really elevate this.</td>', 'The capture of the beams of light really elevate this.', '2010-08-23 14:06:47.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6138736, 904147, 64989, '<td valign="top">Great colors and light.  I love the crisp detail through-out.</td>', 'Great colors and light.  I love the crisp detail through-out.', '2010-08-23 14:07:17.000000', NULL, 1),
(6138738, 903969, 64989, '<td valign="top">This is wonderful.  Tones, curves, angles - it all works for me.  In my top few.</td>', 'This is wonderful.  Tones, curves, angles - it all works for me.  In my top few.', '2010-08-23 14:07:58.000000', NULL, 1),
(6138740, 903906, 64989, '<td valign="top">This reminded me of the Borg cube....which might be the epitome of Architecture.</td>', 'This reminded me of the Borg cube....which might be the epitome of Architecture.', '2010-08-23 14:09:06.000000', NULL, 1),
(6138742, 903578, 64989, '<td valign="top">Great capture of the light on the bridge.  Nice processing on the sky as well.</td>', 'Great capture of the light on the bridge.  Nice processing on the sky as well.', '2010-08-23 14:09:40.000000', NULL, 1),
(6138744, 903307, 64989, '<td valign="top">This feels so serence.  The water is a perfect, smooth glass.  And the warm tones of the buildings agains the cool sky is perfect.</td>', 'This feels so serence.  The water is a perfect, smooth glass.  And the warm tones of the buildings agains the cool sky is perfect.', '2010-08-23 14:10:36.000000', NULL, 1),
(6138746, 903468, 64989, '<td valign="top">Really interesting perspective. Good Job.</td>', 'Really interesting perspective. Good Job.', '2010-08-23 14:11:23.000000', NULL, 1),
(6138748, 904175, 64989, '<td valign="top">I like the play of the reflections in the glass.</td>', 'I like the play of the reflections in the glass.', '2010-08-23 14:11:43.000000', NULL, 1),
(6138749, 903814, 64989, '<td valign="top">Very graphic, and I like the contrast.</td>', 'Very graphic, and I like the contrast.', '2010-08-23 14:12:02.000000', NULL, 1),
(6138751, 904071, 64989, '<td valign="top">I love that this is not literal to the challenge, but instead referential. This feels like it would be at home in an urban office building.</td>', 'I love that this is not literal to the challenge, but instead referential. This feels like it would be at home in an urban office building.', '2010-08-23 14:13:44.000000', NULL, 1),
(6138752, 904200, 64989, '<td valign="top">Wonderful example of architecture, well shot and handled.</td>', 'Wonderful example of architecture, well shot and handled.', '2010-08-23 14:14:16.000000', NULL, 1),
(6138753, 903948, 64989, '<td valign="top">I don''t know where this is, but I want to go visit.</td>', 'I don''t know where this is, but I want to go visit.', '2010-08-23 14:15:06.000000', NULL, 1),
(6138758, 903122, 64989, '<td valign="top">I like the angle used here.  I also appreciate that the sky is not competing with the building and the great colors in the glass.</td>', 'I like the angle used here.  I also appreciate that the sky is not competing with the building and the great colors in the glass.', '2010-08-23 14:16:03.000000', NULL, 1),
(6138765, 903229, 64989, '<td valign="top">This challenge has so many photos of grand and imposing buildings.  I like that your photo is inviting and personal.</td>', 'This challenge has so many photos of grand and imposing buildings.  I like that your photo is inviting and personal.', '2010-08-23 14:17:40.000000', NULL, 1),
(6138766, 903160, 64989, '<td valign="top">Very nice take on one of the most famous and recognizable structures in the world.</td>', 'Very nice take on one of the most famous and recognizable structures in the world.', '2010-08-23 14:19:14.000000', NULL, 1),
(6138767, 903878, 64989, '<td valign="top">This is so cool.  The lines are all about architecture, but it''s so different and refreshing.  The photo scored well with me initially, but then I gave it a "bonus" point for being original.</td>', 'This is so cool.  The lines are all about architecture, but it''s so different and refreshing.  The photo scored well with me initially, but then I gave it a "bonus" point for being original.', '2010-08-23 14:20:31.000000', NULL, 1),
(6138768, 904061, 64989, '<td valign="top">Really cool perspective.</td>', 'Really cool perspective.', '2010-08-23 14:20:54.000000', NULL, 1),
(6138769, 904077, 64989, '<td valign="top">I love the clean compostion and the cool colors working together.  Very Nice.</td>', 'I love the clean compostion and the cool colors working together.  Very Nice.', '2010-08-23 14:21:28.000000', NULL, 1),
(6138772, 904082, 64989, '<td valign="top">I really love the effect of this.  The dramatic processing really works with the structure.</td>', 'I really love the effect of this.  The dramatic processing really works with the structure.', '2010-08-23 14:23:32.000000', NULL, 1),
(6138773, 903438, 64989, '<td valign="top">Lovely.  I wish they would have had the lights on the right on as well, but I certainly can''t fault you for that.</td>', 'Lovely.  I wish they would have had the lights on the right on as well, but I certainly can''t fault you for that.', '2010-08-23 14:24:51.000000', NULL, 1),
(6138774, 904159, 64989, '<td valign="top">Interesting perspective.</td>', 'Interesting perspective.', '2010-08-23 14:25:29.000000', NULL, 1),
(6138776, 903859, 64989, '<td valign="top">Very unique architecture.</td>', 'Very unique architecture.', '2010-08-23 14:26:16.000000', NULL, 1),
(6138777, 903446, 64989, '<td valign="top">I love the glowing effect of the blue windows.</td>', 'I love the glowing effect of the blue windows.', '2010-08-23 14:26:36.000000', NULL, 1),
(6138778, 903521, 64989, '<td valign="top">This is an interesting pattern all on it''s own, well seen.</td>', 'This is an interesting pattern all on it''s own, well seen.', '2010-08-23 14:27:25.000000', NULL, 1),
(6138784, 904195, 83313, '<td valign="top">I like the subject, but the framing and composition comes off to me somewhat awkward. Just one of those personal preference things, and not necessarily a flaw.</td>', 'I like the subject, but the framing and composition comes off to me somewhat awkward. Just one of those personal preference things, and not necessarily a flaw.', '2010-08-23 14:43:44.000000', NULL, 1),
(6138785, 903979, 83313, '<td valign="top">This strikes me as the perspective of an armadillo getting ready to cross.</td>', 'This strikes me as the perspective of an armadillo getting ready to cross.', '2010-08-23 14:44:59.000000', NULL, 1),
(6138788, 903567, 83313, '<td valign="top">I like Yale. They make great locks.</td>', 'I like Yale. They make great locks.', '2010-08-23 14:46:14.000000', NULL, 1),
(6138791, 904056, 83313, '<td valign="top">Interesting subject, but it seems very soft looking with a lot of high ISO noise visible in the ceiling. Shooting at the lowest available ISO and using a tripod could probably get around that issue.</td>', 'Interesting subject, but it seems very soft looking with a lot of high ISO noise visible in the ceiling. Shooting at the lowest available ISO and using a tripod could probably get around that issue.', '2010-08-23 14:50:56.000000', NULL, 1),
(6138793, 903220, 83313, '<td valign="top">A nice sharp and detailed shot, but the cut-off framing of the image is not working for me. Backing off on the zoom a bit might have worked better for my own preferences.</td>', 'A nice sharp and detailed shot, but the cut-off framing of the image is not working for me. Backing off on the zoom a bit might have worked better for my own preferences.', '2010-08-23 14:53:28.000000', NULL, 1),
(6138796, 903913, 83313, '<td valign="top">I think the main problem I am seeing with this shot is the backlighting. It causes the subject to be washed out and the sky is blown with no detail. There is also some visual clutter at the bottom of the frame that doesn''t do much for the scene. In better light, from a different perspective, I think this could be very interesting.</td>', 'I think the main problem I am seeing with this shot is the backlighting. It causes the subject to be washed out and the sky is blown with no detail. There is also some visual clutter at the bottom of the frame that doesn''t do much for the scene. In better light, from a different perspective, I think this could be very interesting.', '2010-08-23 14:58:02.000000', NULL, 1),
(6138798, 904093, 83313, '<td valign="top">Seems a bit soft, perhaps due to a severe crop? There is also a tilt to the tower that I think could have been corrected. I realize this would have tilted the roadway, but if the roadway were sloping upwards, I think that would look more natural than the tower tilted.</td>', 'Seems a bit soft, perhaps due to a severe crop? There is also a tilt to the tower that I think could have been corrected. I realize this would have tilted the roadway, but if the roadway were sloping upwards, I think that would look more natural than the tower tilted.', '2010-08-23 15:01:00.000000', NULL, 1),
(6138799, 903578, 83313, '<td valign="top">Very cool. We are getting a similar bridge in Dallas that is under construction now. I plan to make good use of it for challenges.</td>', 'Very cool. We are getting a similar bridge in Dallas that is under construction now. I plan to make good use of it for challenges.', '2010-08-23 15:03:29.000000', NULL, 1),
(6138802, 903246, 83313, '<td valign="top"><img alt="'' . substr(''//webpages.charter.net/yospiff/Images/Smileys/ciao.gif'', strrpos(''//webpages.charter.net/yospiff/Images/Smileys/ciao.gif'', ''/'') + 1) . ''" border="0" src="//webpages.charter.net/yospiff/Images/Smileys/ciao.gif"/> Hi, Teddy. (No vote, comment only)</td>', ' Hi, Teddy. (No vote, comment only)', '2010-08-23 15:05:21.000000', NULL, 1),
(6138806, 904162, 96997, '<td valign="top">Too dark for my taste.</td>', 'Too dark for my taste.', '2010-08-23 15:15:35.000000', NULL, 1),
(6138807, 903619, 96997, '<td valign="top">Perspective is fine, by the sky colour is irritating ...</td>', 'Perspective is fine, by the sky colour is irritating ...', '2010-08-23 15:16:05.000000', NULL, 1),
(6138809, 903954, 96997, '<td valign="top">The sky is not terribly interesting....</td>', 'The sky is not terribly interesting....', '2010-08-23 15:18:27.000000', NULL, 1),
(6138813, 904145, 96997, '<td valign="top">The sky ruins thos one for me, I''m afraid.</td>', 'The sky ruins thos one for me, I''m afraid.', '2010-08-23 15:25:22.000000', NULL, 1),
(6138817, 904007, 96997, '<td valign="top">This one got the highest rating from me in this challenge - Not sure why it appeals so much to me, but I really like it.</td>', 'This one got the highest rating from me in this challenge - Not sure why it appeals so much to me, but I really like it.', '2010-08-23 15:32:25.000000', NULL, 1),
(6138819, 903307, 96997, '<td valign="top">One of the top-two photos in this challenge in my opinion... nice work.</td>', 'One of the top-two photos in this challenge in my opinion... nice work.', '2010-08-23 15:33:24.000000', NULL, 1),
