(6138874, 904092, 120465, '<td valign="top">Love St. John''s and these houses</td>', 'Love St. John''s and these houses', '2010-08-23 17:02:47.000000', NULL, 1),
(6139109, 903220, 78891, '<td valign="top">I like the sky ... not so much to do with the photo techniques, but it just looks so nice to have a totally blue sky with not a cloud in sight!</td>', 'I like the sky ... not so much to do with the photo techniques, but it just looks so nice to have a totally blue sky with not a cloud in sight!', '2010-08-23 23:16:02.000000', NULL, 1),
(6139110, 903855, 78891, '<td valign="top">I find the branches in the foreground to be a little distracting!</td>', 'I find the branches in the foreground to be a little distracting!', '2010-08-23 23:16:54.000000', NULL, 1),
(6139116, 904113, 78891, '<td valign="top">The shot looks well executed, and this shot would make for a great stock image for a generic corporate website, but I find these shots of glass and steel are kind of common on some contests ... for me it''s not terribly interesting ... but that''s just my opinion, but again, not to put down the shot, as it does look well executed ...</td>', 'The shot looks well executed, and this shot would make for a great stock image for a generic corporate website, but I find these shots of glass and steel are kind of common on some contests ... for me it''s not terribly interesting ... but that''s just my opinion, but again, not to put down the shot, as it does look well executed ...', '2010-08-23 23:23:06.000000', NULL, 1),
(6139118, 903246, 78891, '<td valign="top">Nice big blue sky !!!</td>', 'Nice big blue sky !!!', '2010-08-23 23:23:29.000000', NULL, 1),
